class Solution {
  public int getLargestOutlier(int[] nums) {
    final int OFFSET = 1000;
    int[] count = new int[2 * OFFSET + 1];
    int total = 0;
    for (int x : nums) {
      count[x + OFFSET]++;
      total += x;
    }
    // total = special + sum + outlier, and sum = special, so sum = (total - outlier) / 2
    for (int outlier = OFFSET; outlier >= -OFFSET; outlier--) {
      if (count[outlier + OFFSET] == 0 || (total - outlier) % 2 != 0) continue;
      int sum = (total - outlier) / 2;
      if (sum < -OFFSET || sum > OFFSET) continue;
      int available = count[sum + OFFSET] - (sum == outlier ? 1 : 0);
      if (available > 0) return outlier;
    }
    return -1;
  }
}
